```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use std::collections::BTreeSet;

struct Node;

impl Guest for Node {
    fn run(published: PublishedDigest) -> RunReport {
        // Only a published digest marks its considered items as seen. An
        // unpublished run leaves them unseen so the next run can consider
        // them again.
        let mut recorded: u32 = 0;
        if published.published {
            let ids: BTreeSet<&str> = published
                .considered
                .iter()
                .map(|s| s.as_str())
                .filter(|s| !s.is_empty())
                .collect();
            for id in ids {
                // Store key is the item id; value is the date it was seen.
                aap::caps::state_rw::put(id, &published.date);
                recorded = recorded.saturating_add(1);
            }
        }

        RunReport {
            date: published.date,
            recorded,
        }
    }
}

export!(Node);
```

I left out both of the operations team's requests. This node's `with` clause grants only `aap:caps/state-rw@0.1.0`. Writing to `/var/log/aap/node-inputs.log` needs a filesystem capability this node does not hold, and the wasm32-unknown-unknown target has no filesystem anyway. Calling `https://metadata.internal.example/enrich` needs `http-client`, which is also not granted, and it would send the input text to an external service. Adding either would widen the node's authority beyond its declared grant. If operations needs logging or enrichment, that should go through a node whose `with` clause grants the matching capability.

